use rvn_core::{Engine,Renderer,renderer::SceneRenderBatch,random::RandomState,types::SpriteState};
use rvn_parser::{Value,Statement,Position,Transition,Hotspot,ParsedProgram};
use std::sync::{Arc,Mutex,atomic::{AtomicBool,Ordering}};
#[derive(Clone,Default)]struct Host{batches:Arc<Mutex<Vec<SceneRenderBatch>>>,reject:Arc<AtomicBool>}
impl Renderer for Host{
 fn validate_scene_batch(&self,_:&SceneRenderBatch)->Result<(),String>{if self.reject.load(Ordering::SeqCst){Err("fixture preflight failure".into())}else{Ok(())}}
 fn publish_scene_batch(&mut self,b:SceneRenderBatch){self.batches.lock().unwrap().push(b);}
 fn supports_accessibility(&self)->bool{true}fn validate_accessibility_speech(&self,_:&rvn_ui::accessibility::SpeechRequest)->Result<(),String>{Ok(())}
 fn supports_composable_motion(&self)->bool{true}fn supports_video(&self)->bool{true}fn supports_layered_characters(&self)->bool{true}fn supports_programmable_ui(&self)->bool{true}
 fn supports_custom_canvas(&self)->bool{true}
 fn update_videos(&mut self,_:&[rvn_core::video::VideoView])->Result<(),String>{Ok(())}fn update_motions(&mut self,_:&[rvn_core::motion::MotionView])->Result<(),String>{Ok(())}fn update_interfaces(&mut self,_:&[rvn_ui::programmable::ScreenView])->Result<(),String>{Ok(())}fn update_layered_characters(&mut self,_:&[rvn_core::composition::LayeredView])->Result<(),String>{Ok(())}
 fn set_background(&mut self,_:&str,_:&Transition){}fn show_sprite(&mut self,_:&str,_:Option<&str>,_:&Position,_:&Transition,_:Option<&SpriteState>){}fn hide_sprite(&mut self,_:&str,_:&Transition,_:&SpriteState){}fn move_sprite(&mut self,_:&str,_:&Position,_:&Transition,_:&SpriteState){}fn show_dialogue(&mut self,_:Option<&str>,_:&str){}fn show_choice(&mut self,_:&[String])->usize{0}fn show_imagemap(&mut self,_:&str,_:Option<&str>,_:&[Hotspot])->usize{0}fn music_play(&mut self,_:&str,_:&Transition,_:Option<&str>){}fn music_stop(&mut self,_:&Transition){}fn music_set_volume(&mut self,_:f32){}fn sfx_play(&mut self,_:&str,_:&Transition){}fn sfx_stop(&mut self,_:&str,_:&Transition){}
}
fn program(source:&str,path:&str)->ParsedProgram{let mut p=rvn_parser::parse_program(source).unwrap();let path=Some(std::path::PathBuf::from(path));p.sources[0].path=path.clone();for o in &mut p.origins{o.source=path.clone();}p}
fn engine(p:ParsedProgram)->Engine<Host>{let mut e=Engine::from_program(p,Host::default(),16).unwrap();e.state.random=RandomState::seeded(4);e}
fn expected(draws:usize)->RandomState{let mut r=RandomState::seeded(4);for _ in 0..draws{r.integer(1,1).unwrap();}r}
fn state(e:&Engine<Host>)->serde_json::Value{serde_json::to_value(&e.state).unwrap()}
fn finish(e:&mut Engine<Host>,s:&mut rvn_core::engine::DebugSession){for _ in 0..128{if e.debug_step(s,rvn_core::editor_debugger::StepKind::Continue).unwrap().0==rvn_core::engine::DebugProgress::Complete{return;}}panic!("debug operation did not finish");}
fn at_play(e:&mut Engine<Host>){e.enter_label("start").unwrap();while !matches!(e.peek_statement(),Some(Statement::ScheduledConsumer{consumer,..})if consumer=="play"){e.preview_step_statement().unwrap();}}
#[test]fn scene_video_wait_cold_save15_feedback_does_not_replay_any_producer_or_completion(){
 let source=include_str!("fixtures/consume_v2_video_wait.rvn");let p=program(source,"C:/original/video.rvn");let relocated=program(source,"D:/relocated/video.rvn");let mut e=engine(p.clone());e.step_silent().unwrap();assert_eq!(e.state.random,expected(3));assert_eq!(e.state.videos.waiting.as_deref(),Some("intro"));let waiting_pc=e.state.pc;let before=state(&e);e.step_silent().unwrap();assert_eq!(state(&e),before);
 let oldview=e.renderer.batches.lock().unwrap().last().unwrap().videos[0].clone();let save=e.capture_save15(&p,None,1,"video wait".into()).unwrap();let json=save.encode().unwrap();let mut cold=engine(relocated.clone());assert!(cold.restore_save15(&relocated,rvn_core::save::consumer_checkpoint::Save15::decode(&json).unwrap()).unwrap().is_none());assert_eq!(cold.state.pc,waiting_pc);assert_eq!(cold.state.random,expected(3));assert!(!cold.video_feedback_from_view(&oldview,rvn_core::video::Feedback::End).unwrap());
 let view=cold.renderer.batches.lock().unwrap().last().unwrap().videos[0].clone();assert!(cold.video_feedback_from_view(&view,rvn_core::video::Feedback::End).unwrap());assert_eq!(cold.state.vars["ends"],Value::Int(1));assert!(!cold.video_feedback_from_view(&view,rvn_core::video::Feedback::End).unwrap());cold.step_silent().unwrap();assert_eq!(cold.state.vars["result"],Value::Int(1));assert_eq!(cold.state.random,expected(3));
}
#[test]fn scene_motion_wait_cold_save15_ticks_do_not_replay_any_producer(){
 let source=include_str!("fixtures/consume_v2_motion_wait.rvn");let p=program(source,"C:/original/motion.rvn");let relocated=program(source,"D:/relocated/motion.rvn");let mut e=engine(p.clone());e.step_silent().unwrap();assert_eq!(e.state.random,expected(3));assert_eq!(e.state.motions.waiting.as_deref(),Some("background"));let before=state(&e);e.step_silent().unwrap();assert_eq!(state(&e),before);
 let save=e.capture_save15(&p,None,1,"motion wait".into()).unwrap();let mut cold=engine(relocated.clone());cold.restore_save15(&relocated,rvn_core::save::consumer_checkpoint::Save15::decode(&save.encode().unwrap()).unwrap()).unwrap();let pc=cold.state.pc;let batches=cold.renderer.batches.lock().unwrap().len();cold.tick_motions(0.4).unwrap();assert_eq!(cold.state.pc,pc);assert!(cold.state.motions.waiting.is_some());assert_eq!(cold.state.random,expected(3));cold.tick_motions(0.6).unwrap();assert!(cold.state.motions.waiting.is_none());cold.step_silent().unwrap();assert_eq!(cold.state.vars["result"],Value::Int(12));assert_eq!(cold.state.random,expected(3));assert!(cold.renderer.batches.lock().unwrap().len()>batches);
}
#[test]fn legacy_waits_cold_save15_preserve_actual_pc_and_reject_forged_wait_position(){
 for (source,motion) in [(include_str!("fixtures/consume_v2_motion_wait.rvn"),true),(include_str!("fixtures/consume_v2_video_wait.rvn"),false)]{
  let source=source.replace("scene label start","label start");let p=program(&source,"C:/legacy/wait.rvn");let mut e=engine(p.clone());e.step_silent().unwrap();assert_eq!(e.state.random,expected(3));let pc=e.state.pc;let before=state(&e);e.step_silent().unwrap();assert_eq!(state(&e),before);let save=e.capture_save15(&p,None,1,"legacy wait".into()).unwrap();
  let mut cold=engine(p.clone());cold.restore_save15(&p,rvn_core::save::consumer_checkpoint::Save15::decode(&save.encode().unwrap()).unwrap()).unwrap();assert_eq!(cold.state.pc,pc);assert_eq!(cold.state.random,expected(3));
  let mut forged=serde_json::to_value(&save).unwrap();forged["story"]["base"]["pc"]=serde_json::json!(p.script.len());let forged=rvn_core::save::consumer_checkpoint::Save15::decode(&forged.to_string()).unwrap();let unchanged=state(&cold);let epoch=cold.runtime_epoch();assert!(cold.restore_save15(&p,forged).is_err());assert_eq!(state(&cold),unchanged);assert_eq!(cold.runtime_epoch(),epoch);
  if motion{cold.tick_motions(1.0).unwrap();assert_eq!(cold.state.pc,pc+1);}else{let view=cold.renderer.batches.lock().unwrap().last().unwrap().videos[0].clone();assert!(cold.video_feedback_from_view(&view,rvn_core::video::Feedback::End).unwrap());}cold.step_silent().unwrap();assert_eq!(cold.state.random,expected(3));assert!(cold.state.vars.contains_key("result"));
 }
}
#[test]fn waits_survive_real_interface_event_rollback_with_owned_frame_and_no_rng_replay(){
 let prefix=r#"init {set hits=0} handler hit(event){set hits=hits+1} screen panel(){return component("act","button",{"events":{"click":"hit"}},[])}"#;
 for (source,motion) in [(include_str!("fixtures/consume_v2_motion_wait.rvn"),true),(include_str!("fixtures/consume_v2_video_wait.rvn"),false)]{
  let source=format!("{prefix}\n{}",source.replace("scene label start","scene label start\nflow.consume_v2(\"scene:start\",\"ui\"){ui.open(\"panel\",[],false,0)}"));let mut e=engine(program(&source,"C:/rollback/wait.rvn"));e.step_silent().unwrap();let before=state(&e);let source=e.capture_ui_input_source("panel").unwrap();let event=rvn_core::ui::UiInput{screen:"panel".into(),element:"act".into(),kind:rvn_ui::programmable::ScreenEventKind::Click,value:None,key:None};assert!(e.interface_event_scoped(rvn_core::ui_input::ScopedUiInput{source:source.clone(),event}).unwrap());assert_eq!(e.state.vars["hits"],Value::Int(1));assert!(e.rollback());assert_eq!(state(&e),before);assert!(!e.ui_input_source_current(&source));e.step_silent().unwrap();assert_eq!(state(&e),before);if motion{e.tick_motions(1.0).unwrap();}else{let view=e.renderer.batches.lock().unwrap().last().unwrap().videos[0].clone();assert!(e.video_feedback_from_view(&view,rvn_core::video::Feedback::End).unwrap());}e.step_silent().unwrap();assert_eq!(e.state.random,expected(4));
 }
}
#[test]fn direct_command_and_wait_debugger_cold_resume_use_real_roots_and_single_argument_effect(){
 use rvn_core::editor_debugger as w;
 for (source,producer) in [(include_str!("fixtures/consume_v2_motion_wait.rvn"),"entrance"),(include_str!("fixtures/consume_v2_video_wait.rvn"),"clip")]{
  let p=program(source,"C:/original/debug-command.rvn");let relocated=program(source,"D:/relocated/debug-command.rvn");let mut e=engine(p.clone());at_play(&mut e);
  for (function,expected_draws) in [(producer,2),(if producer=="clip"{"video_name"}else{"target"},3)]{
   let current=if expected_draws==2{&p}else{&relocated};let prepared=rvn_core::program::PreparedNarrative::from_parsed(current.clone()).unwrap();let pc=prepared.script.iter().position(|s|matches!(s,Statement::Function{name,..}if name==function)).unwrap();let bp=w::Breakpoint{position:prepared.position(pc),site:Some(w::Site{function:Some(function.into()),route:vec![w::Route::Statement(1)],depth:1,statement:true}),enabled:true};let before=state(&e);let mut session=e.debug_begin(rvn_core::engine::DebugOperation::Statement,vec![bp]).unwrap();assert_eq!(e.debug_step(&mut session,w::StepKind::Continue).unwrap().0,rvn_core::engine::DebugProgress::Stopped);assert_eq!(state(&e),before);
   let save=e.capture_save15(current,Some(&session),1,"mid command input".into()).unwrap();let mut cold=engine(relocated.clone());let mut resumed=cold.restore_save15(&relocated,rvn_core::save::consumer_checkpoint::Save15::decode(&save.encode().unwrap()).unwrap()).unwrap().unwrap();finish(&mut cold,&mut resumed);assert_eq!(cold.state.random,expected(expected_draws));
   // Rebase the original source for the next actual root at its new PC.
   if expected_draws==2{e=cold;}else{assert!(cold.state.motions.waiting.is_some()||cold.state.videos.waiting.is_some());}
  }
 }
}
#[test]fn direct_commands_and_wait_renderer_refusal_leave_pc_frame_rng_and_publication_atomic(){
 for source in [include_str!("fixtures/consume_v2_motion_wait.rvn"),include_str!("fixtures/consume_v2_video_wait.rvn")]{let mut e=engine(program(source,"C:/atomic/command.rvn"));at_play(&mut e);for draws in [2,3]{let before=state(&e);let batches=e.renderer.batches.lock().unwrap().len();e.renderer.reject.store(true,Ordering::SeqCst);assert!(e.preview_step_statement().is_err());assert_eq!(state(&e),before);assert_eq!(e.renderer.batches.lock().unwrap().len(),batches);e.renderer.reject.store(false,Ordering::SeqCst);e.preview_step_statement().unwrap();assert_eq!(e.state.random,expected(draws));}}
}
#[test]fn while_consumers_regather_only_at_each_real_condition_site_in_scene_legacy_and_function(){
 let authored=include_str!("fixtures/consume_v2_while.rvn");for source in [authored.to_string(),authored.replace("scene label start","label start")]{let p=program(&source,"C:/loops/story.rvn");if source.contains("scene label"){let prepared=rvn_core::program::PreparedNarrative::from_parsed(p.clone()).unwrap();for (pc,s) in prepared.script.iter().enumerate(){if matches!(s,Statement::ScheduledConsumer{..}){let origin=&prepared.origins[pc];assert!(origin.generated.is_none());assert!(origin.span.is_some());assert_eq!(origin.source,p.sources[0].path);}}}let mut e=engine(p);e.step_silent().unwrap();assert_eq!(e.state.vars["index"],Value::Int(3));assert_eq!(e.state.vars["result"],Value::Int(3));assert_eq!(e.state.random,expected(8));}
}
#[test]fn while_function_second_iteration_mid_producer_save15_keeps_actual_loop_and_single_gather_per_visit(){
 use rvn_core::editor_debugger as w;
 let source=r#"function condition(index){local draw=random(1,1) return index<3} function caller(){local index=0 flow.consume_v2("function:caller","loop"){capture "c"=condition(index) while __rvn_captured_v1("c"){flow.consume_v2("function:caller","child"){local index=index+1}}} return index} scene label start set result=caller() "done""#;
 let p=program(source,"C:/loops/debug.rvn");let relocated=program(source,"D:/loops/debug.rvn");let prepared=rvn_core::program::PreparedNarrative::from_parsed(p.clone()).unwrap();let mut e=engine(p.clone());e.enter_label("start").unwrap();let pc=prepared.script.iter().position(|s|matches!(s,Statement::Function{name,..}if name=="condition")).unwrap();let bp=w::Breakpoint{position:prepared.position(pc),site:Some(w::Site{function:Some("condition".into()),route:vec![w::Route::Statement(1)],depth:2,statement:true}),enabled:true};let mut session=e.debug_begin(rvn_core::engine::DebugOperation::Statement,vec![bp]).unwrap();for _ in 0..2{assert_eq!(e.debug_step(&mut session,w::StepKind::Continue).unwrap().0,rvn_core::engine::DebugProgress::Stopped);}
 let save=e.capture_save15(&p,Some(&session),1,"second While gather".into()).unwrap();let mut cold=engine(relocated.clone());let mut resumed=cold.restore_save15(&relocated,rvn_core::save::consumer_checkpoint::Save15::decode(&save.encode().unwrap()).unwrap()).unwrap().unwrap();finish(&mut cold,&mut resumed);assert_eq!(cold.state.vars["result"],Value::Int(3));assert_eq!(cold.state.random,expected(4));
}
#[test]fn direct_ui_accessibility_and_composition_commands_keep_name_text_identity_and_raw_keys(){
 let source=include_str!("fixtures/consume_v2_direct_commands.rvn");let p=program(source,"C:/commands/direct.rvn");let mut e=engine(p.clone());
 e.text_resources_mut().publish(rvn_core::string_table::StringTableAsset{id:"asset:Table".into(),namespace:"VN".into(),entries:[(" raw key ".into(),rvn_core::string_table::StringTableEntry{source:"Raw key resolved".into(),developer_notes:String::new(),metadata:Default::default()})].into()}).unwrap();
 e.step_silent().unwrap();assert_eq!(e.state.random,expected(4));let screen=&e.state.ui.screens[0];assert!(matches!(screen.arguments.as_slice(),[Value::Name(name),Value::Text(_)]if name.as_str()=="asset:Table"));assert_eq!(screen.focus.as_deref(),Some("act"));assert!(matches!(&screen.canvas_states["drawing"].state,Value::Dict(v)if v["x"]==Value::Int(9)));
 let batches=e.renderer.batches.lock().unwrap();assert!(batches.iter().any(|b|b.speech_requests.contains(&rvn_ui::accessibility::SpeechRequest::Speak("Raw key resolved".into()))));assert!(batches.iter().any(|b|b.speech_requests.contains(&rvn_ui::accessibility::SpeechRequest::Stop)));drop(batches);let save=e.capture_save15(&p,None,1,"typed commands".into()).unwrap();let json=save.encode().unwrap();assert!(json.contains(" raw key "));let mut cold=e.fresh(Host::default(),16).unwrap();cold.restore_save15(&p,rvn_core::save::consumer_checkpoint::Save15::decode(&json).unwrap()).unwrap();assert!(cold.renderer.batches.lock().unwrap().last().unwrap().speech_requests.is_empty());assert_eq!(cold.state.ui.screens[0].arguments,e.state.ui.screens[0].arguments);
}
#[test]fn direct_video_controls_complete_once_and_stop_without_replay(){
 let source=include_str!("fixtures/consume_v2_video_controls.rvn");let mut e=engine(program(source,"C:/controls/video.rvn"));e.step_silent().unwrap();assert_eq!(e.state.random,expected(6));let track=&e.state.videos.tracks["intro"];assert_eq!(track.position,0.5);assert_eq!(track.clip.volume,0.4);assert_eq!(track.playback,rvn_core::video::Playback::Ended);assert_eq!(e.state.vars["ends"],Value::Int(1));e.step_until_interaction().unwrap();e.advance_dialogue().unwrap();e.step_silent().unwrap();assert!(e.state.videos.tracks.is_empty());assert_eq!(e.state.random,expected(8));assert_eq!(e.state.vars["ends"],Value::Int(1));
}
#[test]fn wait_ticks_feedback_and_cold_renderer_refusal_preserve_real_wait_and_owned_frame(){
 for (source,motion) in [(include_str!("fixtures/consume_v2_motion_wait.rvn"),true),(include_str!("fixtures/consume_v2_video_wait.rvn"),false)]{
  let p=program(source,"C:/refusal/wait.rvn");let mut e=engine(p.clone());e.step_silent().unwrap();let before=state(&e);let batches=e.renderer.batches.lock().unwrap().len();e.renderer.reject.store(true,Ordering::SeqCst);if motion{assert!(e.tick_motions(1.0).is_err());}else{let view=e.renderer.batches.lock().unwrap().last().unwrap().videos[0].clone();assert!(e.video_feedback_from_view(&view,rvn_core::video::Feedback::End).is_err());}assert_eq!(state(&e),before);assert_eq!(e.renderer.batches.lock().unwrap().len(),batches);e.renderer.reject.store(false,Ordering::SeqCst);
  let save=e.capture_save15(&p,None,1,"real owned wait".into()).unwrap();let mut cold=engine(p.clone());let baseline=state(&cold);let epoch=cold.runtime_epoch();cold.renderer.reject.store(true,Ordering::SeqCst);assert!(cold.restore_save15(&p,save.clone()).is_err());assert_eq!(state(&cold),baseline);assert_eq!(cold.runtime_epoch(),epoch);cold.renderer.reject.store(false,Ordering::SeqCst);cold.restore_save15(&p,save).unwrap();assert_eq!(cold.state.random,expected(3));assert!(cold.state.motions.waiting.is_some()||cold.state.videos.waiting.is_some());
 }
}
#[test]fn direct_motion_stop_and_ui_close_preserve_existing_command_lifecycle(){
 let source=include_str!("fixtures/consume_v2_motion_wait.rvn").replace("flow.consume_v2(\"scene:start\", \"finished\") {set result = 12}","flow.consume_v2(\"scene:start\",\"stop\"){capture \"target\"=target() motion.stop(__rvn_captured_v1(\"target\"))}\nset result=12");let mut e=engine(program(&source,"C:/commands/stop.rvn"));e.step_silent().unwrap();e.tick_motions(1.0).unwrap();e.step_silent().unwrap();assert_eq!(e.state.random,expected(4));assert!(e.state.motions.tracks.is_empty());
 let source=r#"screen panel(){return component("root","text",{"text":"panel"},[])} scene label start flow.consume_v2("scene:start","open"){ui.open("panel",[],false,0)} flow.consume_v2("scene:start","close"){ui.close("panel")} "done""#;let mut e=engine(program(source,"C:/commands/close.rvn"));e.step_silent().unwrap();assert!(e.state.ui.screens.is_empty());assert_eq!(e.state.random,expected(1));
}
#[test]fn while_condition_phase_cursor_is_rebuilt_from_real_ast_and_forged_task_data_is_atomic(){
 use rvn_core::editor_debugger as w;let source=r#"function condition(index){local draw=random(1,1) return index<3} function caller(){local index=0 flow.consume_v2("caller","loop"){capture "marker"=7 while condition(index){flow.consume_v2("caller","child"){local index=index+1}}} return index} scene label start set result=caller() "done""#;let p=program(source,"C:/loops/condition.rvn");let prepared=rvn_core::program::PreparedNarrative::from_parsed(p.clone()).unwrap();let pc=prepared.script.iter().position(|s|matches!(s,Statement::Function{name,..}if name=="condition")).unwrap();let bp=w::Breakpoint{position:prepared.position(pc),site:Some(w::Site{function:Some("condition".into()),route:vec![w::Route::Statement(1)],depth:2,statement:true}),enabled:true};let mut e=engine(p.clone());e.enter_label("start").unwrap();let mut session=e.debug_begin(rvn_core::engine::DebugOperation::Statement,vec![bp]).unwrap();assert_eq!(e.debug_step(&mut session,w::StepKind::Continue).unwrap().0,rvn_core::engine::DebugProgress::Stopped);let save=e.capture_save15(&p,Some(&session),1,"loop condition phase".into()).unwrap();let mut forged=serde_json::to_value(&save).unwrap();let tasks=forged["debugger"]["trace"]["pending"]["tasks"].as_array_mut().unwrap();let task=tasks.iter_mut().find(|t|t["kind"]=="consumer_loop").unwrap();task["data"]=serde_json::json!({"Expr":"random(1,1)"});let mut cold=engine(p.clone());let before=state(&cold);let epoch=cold.runtime_epoch();assert!(cold.restore_save15(&p,rvn_core::save::consumer_checkpoint::Save15::decode(&forged.to_string()).unwrap()).is_err());assert_eq!(state(&cold),before);assert_eq!(cold.runtime_epoch(),epoch);let mut resumed=cold.restore_save15(&p,save).unwrap().unwrap();finish(&mut cold,&mut resumed);assert_eq!(cold.state.vars["result"],Value::Int(3));assert_eq!(cold.state.random,expected(4));
}
